param([Parameter(Mandatory=$true)][ValidateRange(1,2147483647)][int]$RendererPid,[Parameter(Mandatory=$true)][ValidateRange(1,2147483647)][int]$RendererParentPid,[Parameter(Mandatory=$true)][string]$RendererPath,[Parameter(Mandatory=$true)][string]$AppVersion)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
function Row([int]$Id){$rows=@(Get-CimInstance -ClassName Win32_Process -OperationTimeoutSec 5 -Filter ('ProcessId='+$Id));if($rows.Count -ne 1){throw 'PROCESS_IDENTITY_UNAVAILABLE'};$r=$rows[0];return [pscustomobject]@{processId=[int]$r.ProcessId;parentProcessId=[int]$r.ParentProcessId;sessionId=[int]$r.SessionId;createdUtc=([DateTime]$r.CreationDate).ToUniversalTime().ToString('o');executablePath=[string]$r.ExecutablePath}}
$renderer=Row $RendererPid;if($renderer.parentProcessId -ne $RendererParentPid -or $renderer.executablePath -ine $RendererPath){throw 'RENDERER_IDENTITY_CHANGED'}
$bridge=Row $renderer.parentProcessId;$main=Row $bridge.parentProcessId;$root=[IO.Path]::GetDirectoryName($main.executablePath)
if([IO.Path]::GetFileName($main.executablePath) -ine 'AfterFX.exe' -or $renderer.executablePath -ine (Join-Path $root 'CEPHtmlEngine\CEPHtmlEngine.exe') -or $bridge.executablePath -ine $renderer.executablePath -or $main.sessionId -ne $renderer.sessionId -or $bridge.sessionId -ne $renderer.sessionId){throw 'EXACT_CEP_PARENT_CHAIN_REQUIRED'}
$exe=Join-Path $root 'AfterFX.exe';$com=Join-Path $root 'AfterFX.com'
[pscustomobject]@{platform='win32';appVersion=$AppVersion;rendererPid=$RendererPid;processes=@($renderer,$bridge,$main);images=@{exe=@{path=$exe;sha256=(Get-FileHash -LiteralPath $exe -Algorithm SHA256).Hash.ToLowerInvariant()};com=@{path=$com;sha256=(Get-FileHash -LiteralPath $com -Algorithm SHA256).Hash.ToLowerInvariant()}}}|ConvertTo-Json -Depth 6 -Compress
